import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    sale_mask = (df['row_kind'] == 'sale') & (df['Currency'] == 'USD')
    dfs = df[sale_mask].copy()

    last_ship_date = dfs['Ship Date'].max()

    def is_otd_numerator(row):
        return (
            row['days_before_promise'] >= 0 and
            row['transit_days'] >= 0
        )

    def is_otd_denominator(row):
        if row['transit_days'] >= 0:
            if row['days_before_promise'] >= 0:
                return True
            if row['days_late'] > 0:
                return True
        status_lower = str(row['Status']).strip().lower()
        rts_statuses = {'returned to sender', 'return to sender', 'rts', 'returned', 'refused'}
        if status_lower in rts_statuses and row['transit_days'] >= 0:
            return True
        open_statuses = {
            'in transit', 'out for delivery', 'picked up', 'exception',
            'delivery exception', 'delayed', 'tendered', 'booked', 'dispatched',
            'pending', 'shipped', 'partially shipped', 'backordered',
            'short shipped', 'open', 'allocated', 'released', 'picked', 'packed'
        }
        if status_lower in open_statuses and row['days_past_due'] > 0:
            return True
        return False

    dfs['_otd_num'] = dfs.apply(is_otd_numerator, axis=1).astype(int)
    dfs['_otd_den'] = dfs.apply(is_otd_denominator, axis=1).astype(int)

    carriers = dfs.groupby('Carrier').agg(
        num=('_otd_num', 'sum'),
        den=('_otd_den', 'sum')
    ).reset_index()
    carriers['otd_rate'] = carriers.apply(
        lambda r: r['num'] / r['den'] if r['den'] > 0 else float('nan'), axis=1
    )
    carriers_sorted = carriers.sort_values('den', ascending=False).head(10)

    otd_results = [
        {"name": str(row['Carrier']), "value": round(float(row['otd_rate']), 4)}
        for _, row in carriers_sorted.iterrows()
        if not (row['otd_rate'] != row['otd_rate'])
    ]

    total_num = int(dfs['_otd_num'].sum())
    total_den = int(dfs['_otd_den'].sum())
    overall_otd = round(total_num / total_den, 4) if total_den > 0 else float('nan')

    result['segments'].append({
        "segment_column": "Carrier",
        "metric_column": "Delivered At",
        "aggregation": "ratio",
        "label": "on_time_delivery",
        "results": otd_results
    })

    result['segments'].append({
        "segment_column": "Carrier",
        "metric_column": "Delivered At",
        "aggregation": "ratio",
        "label": "on_time_delivery_overall",
        "results": [{"name": "Overall", "value": overall_otd}]
    })

    result['assumptions'].append(
        f"on_time_delivery denominator={total_den}, numerator={total_num}; "
        f"open-not-yet-due shipments excluded; sale+USD rows only"
    )
    result['assumptions'].append(
        "days_before_promise, days_late, days_past_due, transit_days used as provided; not recomputed"
    )

except Exception as e:
    result['segments'].append({
        "segment_column": "Carrier",
        "metric_column": "Delivered At",
        "aggregation": "ratio",
        "label": "on_time_delivery",
        "results": [{"name": "error", "value": -1.0}]
    })
    result['assumptions'].append(f"Segmentation error: {str(e)}")

